import * as React from "react";
import "./RadioButton.scss";
import { MpaIcon } from "../icon/MpaIcon";

export interface RadioButtonProps {

  /**
  * Identifying value for the radio button
  */
  id?: string;
   /**
  * Identifying name for the radio button
  */
  name?: string;
  /**
   * Identify the radio button value.
   */
  value?: string;

  /**
   * Determines whether this radio button is checked.
   */
  checked?: boolean; 

  /**
   * Hex code that determines the background colour of the field when it is checked.
   */
  colour?: "primary" | "secondary" | "tertiary";
  
  onChange?: (event: React.ChangeEvent<HTMLInputElement>) => void;
  /**
   * Boolean that determines if the radio button can be interacted with.
   */
  disabled?: boolean;
  /**
   * Text to be displayed below the input field in case of an error.
   */
    errorText?: string;
  /**
   * Custom classNames that can be provided for style extension / overrides.
   */
  className?: string;

  /**
   * The string to be displayed beside the radio button.
  */
  label?: string;

}

export const RadioButton: React.FC<RadioButtonProps> = ({
  id,
  label="Default Label",
  onChange,
  colour ="primary",
  disabled = false,
  className="",
  value,
  checked,
  name,
  errorText="",
  
}) => {
  const wrapperClassName = `radio-button-wrapper`;
  const disabledClassName = `${disabled ? "disabled" : ""}`


  return (
    <div className={`${wrapperClassName} ${className}`}>
        <label className={`radio-container ${disabledClassName}`}>
          <div className={`radio-button-item ${disabledClassName}`}>
            <input
              type="radio"
              id={id}
              name={name}
              className={`radio-button-input ${colour} ${disabledClassName}`}
              checked={checked}
              value={value}
              onChange={onChange}
              disabled={disabled}
            />
             <span className={`custom-radio ${colour} ${disabled ? "disabled" : ""}`}></span> 
            <div className={`hover-shadow ${colour}` }></div>
          </div>
          <div className={`radio-button-label ${disabled ? "disabled" : ""}`} >{label}  </div>
        </label>

        {errorText?.trim() !== ""   && (
          <div>         
              <p className="error-text"><MpaIcon iconName="AlertCircle" colour="var(--mpa-red-80)"/>
              <span className="error-text-padding">
              {errorText}
              </span>
              </p>
          </div>
        )}

    </div>
  );
};

export default RadioButton;
